INT = "int"
FLOAT = "float"
STRING = "string"
TIMESTAMP = "timestamp"
BOOL = "bool"

_NUMERIC = (INT, FLOAT)


def is_numeric(t):
    return t in _NUMERIC


def is_string(t):
    return t == STRING


def is_timestamp(t):
    return t == TIMESTAMP


def is_bool(t):
    return t == BOOL


def is_int(t):
    return t == INT


def _kind(t):
    return "number" if t in _NUMERIC else t


def can_compare(a, b):
    """True if values of types a and b may be tested for (in)equality."""
    return _kind(a) == _kind(b)


def can_order(a, b):
